# How long a press takes in a hosted game: a GBA test program on the mGBA core turns the screen white and plays a
# tone while A is held. The script presses A 40 times (no real input, the launcher needn't be in front) and the
# launcher stamps when the press was read by the game, the first frame with it, the picture handed to Windows,
# the sound made and the sound handed to the device (LatencyProbe.cs). The tone is heard on the default device.
# Usage: lat1-input-delay.ps1 -Exe <Launcher.exe> [-Core <mgba_libretro.dll>] [-Root <dir>]   (wipes <dir>)
#   -Pos x,y -Size wxh: where the window goes (default off screen; on screen to watch the picture itself).
param([string]$Exe = "$PSScriptRoot\..\bin\publish\Launcher.exe", [string]$Core = $env:IONEA_TEST_MGBA_CORE, [string]$Root = "$env:TEMP\Ionea-tests\lat1", [string]$Pos = "-30000,-30000", [string]$Size = "1040x620")
$ErrorActionPreference = 'Stop'
if (-not $Core -or -not (Test-Path $Core)) { "Give -Core <path to mgba_libretro.dll> (or IONEA_TEST_MGBA_CORE)"; exit 1 }
if (Test-Path $Root) { Remove-Item $Root -Recurse -Force }
New-Item -ItemType Directory -Force "$Root\roms", "$Root\emus\Cores", "$Root\data" | Out-Null
Copy-Item $Core "$Root\emus\Cores\mgba_libretro.dll"
function New-Rom([string]$name, [string]$title, [string]$code) {
  $rom = New-Object byte[] 512
  [byte[]]$logo = 0x24,0xFF,0xAE,0x51,0x69,0x9A,0xA2,0x21,0x3D,0x84,0x82,0x0A,0x84,0xE4,0x09,0xAD,0x11,0x24,0x8B,0x98,0xC0,0x81,0x7F,0x21,0xA3,0x52,0xBE,0x19,0x93,0x09,0xCE,0x20,0x10,0x46,0x4A,0x4A,0xF8,0x27,0x31,0xEC,0x58,0xC7,0xE8,0x33,0x82,0xE3,0xCE,0xBF,0x85,0xF4,0xDF,0x94,0xCE,0x4B,0x09,0xC1,0x94,0x56,0x8A,0xC0,0x13,0x72,0xA7,0xFC,0x9F,0x84,0x4D,0x73,0xA3,0xCA,0x9A,0x61,0x58,0x97,0xA3,0x27,0xFC,0x03,0x98,0x76,0x23,0x1D,0xC7,0x61,0x03,0x04,0xAE,0x56,0xBF,0x38,0x84,0x00,0x40,0xA7,0x0E,0xFD,0xFF,0x52,0xFE,0x03,0x6F,0x95,0x30,0xF1,0x97,0xFB,0xC0,0x85,0x60,0xD6,0x80,0x25,0xA9,0x63,0xBE,0x03,0x01,0x4E,0x38,0xE2,0xF9,0xA2,0x34,0xFF,0xBB,0x3E,0x03,0x44,0x78,0x00,0x90,0xCB,0x88,0x11,0x3A,0x94,0x65,0xC0,0x7C,0x63,0x87,0xF0,0x3C,0xAF,0xD6,0x25,0xE4,0x8B,0x38,0x0A,0xAC,0x72,0x21,0xD4,0xF8,0x07
  [Array]::Copy($logo, 0, $rom, 4, $logo.Length)
  [byte[]]$b = 0x2E,0x00,0x00,0xEA; [Array]::Copy($b, 0, $rom, 0, 4)          # b 0xC0 (past the header)
  # While A is held: the backdrop is white and sound channel 2 plays about 1 kHz (made by hand, ARM code).
  [byte[]]$prog = 0x01,0x03,0xA0,0xE3,0x00,0x10,0xA0,0xE3,0xB0,0x10,0xC0,0xE1,0x80,0x10,0xA0,0xE3,0xB4,0x18,0xC0,0xE1,0x22,0x1C,0xA0,0xE3,0x77,0x10,0x81,0xE3,0xB0,0x18,0xC0,0xE1,0x02,0x10,0xA0,0xE3,0xB2,0x18,0xC0,0xE1,0x05,0x54,0xA0,0xE3,0x01,0x4C,0x80,0xE2,0x01,0x60,0xA0,0xE3,0xB6,0x20,0xD0,0xE1,0xA0,0x00,0x52,0xE3,0xFC,0xFF,0xFF,0x0A,0xB6,0x20,0xD0,0xE1,0xA0,0x00,0x52,0xE3,0xFC,0xFF,0xFF,0x1A,0xB0,0x33,0xD4,0xE1,0x01,0x30,0x03,0xE2,0x06,0x00,0x53,0xE1,0xF5,0xFF,0xFF,0x0A,0x03,0x60,0xA0,0xE1,0x00,0x00,0x53,0xE3,0x7F,0x1C,0xA0,0x03,0xFF,0x10,0x81,0x03,0x00,0x10,0xA0,0x13,0xB0,0x10,0xC5,0xE1,0x02,0x19,0xA0,0x03,0x80,0x10,0x81,0x03,0x80,0x10,0xA0,0x13,0xB8,0x16,0xC0,0xE1,0x87,0x1C,0xA0,0xE3,0x7D,0x10,0x81,0xE3,0xBC,0x16,0xC0,0xE1,0xE7,0xFF,0xFF,0xEA
  [Array]::Copy($prog, 0, $rom, 0xC0, $prog.Length)
  $t = [Text.Encoding]::ASCII.GetBytes($title); [Array]::Copy($t, 0, $rom, 0xA0, $t.Length)
  if ($code) { $c4 = [Text.Encoding]::ASCII.GetBytes($code); [Array]::Copy($c4, 0, $rom, 0xAC, 4) }
  $rom[0xB2] = 0x96
  $c = 0; for ($i = 0xA0; $i -le 0xBC; $i++) { $c = ($c - $rom[$i]) -band 0xFF }; $rom[0xBD] = ($c - 0x19) -band 0xFF
  [IO.File]::WriteAllBytes("$Root\roms\$name.gba", $rom)
}
New-Rom "Latency Test" "LATENCYTEST " $null

$fails = 0
function Check($ok, $what) { if ($ok) { "ok   $what" } else { "FAIL $what"; $script:fails++ } }
$env:IONEA_TESTROOT = $Root
$a = "--data `"$Root\data`" --no-import --emulators `"$Root\emus`" --windowed --mute --game-sound --size $Size --pos $Pos --script `"$PSScriptRoot\lat1-input-delay.txt`""
$p = Start-Process $Exe -ArgumentList $a -PassThru
if (-not $p.WaitForExit(180000)) { $p.Kill(); "FAIL the launcher did not finish"; exit 1 }
$log = Get-Content "$Root\data\launcher.log"
$log | Select-String 'SCRIPT FAIL' | ForEach-Object { "    $_" }
Check (@($log | Select-String 'SCRIPT done, 0 failed').Count -eq 1) 'the script ran clean'
Check (@($log | Select-String 'core sound: low-latency output').Count -ge 1) 'the low-latency output opened'
Check (@($log | Select-String 'core picture: straight to the screen').Count -ge 1) 'the picture went straight to the screen'
$sum = $log | Select-String 'SCRIPT latency: ' | Select-Object -Last 1
Check ($sum -and $sum.Line -match 'frame with it [\d.]+ ms \(min [\d.]+, max [\d.]+, 40/40\)') 'every press showed in the picture'
Check ($sum -and $sum.Line -match 'sound to the device [\d.]+ ms \(min [\d.]+, max [\d.]+, 40/40\)') 'every press was heard'
if ($sum) { (($sum.Line -replace "^.*SCRIPT latency: ", "") -split '; ') | ForEach-Object { "     $_" } }
"lat1: $fails failed"
exit $fails
